from fractions import Fraction

def silicate_formula(shared):
    s = Fraction(shared).limit_denominator(12)
    oxygens = 4 - s / 2            # oxygens per silicon: each shared corner counts one half
    charge = 4 - 2 * oxygens       # charge per silicon: Si is +4, each O is -2
    n_si = 1                       # smallest number of Si atoms that makes both counts whole
    while (oxygens * n_si).denominator != 1 or (charge * n_si).denominator != 1:
        n_si += 1
    formula = ("Si" if n_si == 1 else f"Si{n_si}") + f"O{int(oxygens * n_si)}"
    return formula, int(charge * n_si)
